{
  "title": "坦白与新生",
  "synopsis": "周野向街坊公开道歉并坦白真相，两人在理解与托底中达成合作整改的约定。",
  "preview_blurb": "面对窗外催促的街坊，周野能否放下恐惧坦白断电真相？",
  "scenes": [
    {
      "title": "谎言的尽头",
      "location": "广播站控制台",
      "dramatic_goal": "周野试图插电掩饰，被林岚制止并逼迫其直面现实。",
      "lines": [
        {
          "kind": "sfx",
          "text": "窗外传来街坊们聚集的敲门声与呼喊：“小周，到点了，怎么还不播音？”"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我……我这就插上！只要通电了，大家就以为只是跳闸，评估的事就能再拖一天！岚哥，你帮帮我，就这一次！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "放手。现在插上去，就是骗他们。你拔下插头的那一刻，就该知道纸包不住火。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "可是明天上午街道办就来做撤并评估了！我不能让广播站就这么没了，我不能连个播音员都不是了！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "瞒得住机器，瞒不住人心。你听听外面的声音，他们等的是你的实话，不是你编造的假象。"
        }
      ]
    },
    {
      "title": "坦白与宽慰",
      "location": "广播站控制台",
      "dramatic_goal": "周野放弃掩饰，通过备用扩音器向街坊公开道歉并获得原谅。",
      "lines": [
        {
          "kind": "sfx",
          "text": "周野手抖着停下，深吸一口气，放下插头，打开桌上的干电池备用扩音喇叭，电流底噪响起。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "街坊们……对不起。设备没坏，是我……是我自己拔了电源。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "明天街道要做撤并评估，我太害怕失去这里，害怕自己变得毫无价值，就想制造故障拖延时间。对不起，我骗了大家，我是个懦夫。"
        },
        {
          "kind": "sfx",
          "text": "窗外短暂安静后，传来老街坊温和的安慰：“傻孩子，广播站没了，咱们街坊情分还在。”"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "王奶奶……谢谢您的安慰，街坊情分，我记在心里了。"
        }
      ]
    },
    {
      "title": "技术背书与新开始",
      "location": "广播站控制台",
      "dramatic_goal": "林岚提供专业托底，两人达成合作整改的约定，宣告广播站重生。",
      "lines": [
        {
          "kind": "sfx",
          "text": "纸张翻动，笔尖摩擦纸张声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "擦擦眼泪。评估报告我来写技术背书。“设备老化，需全面整改升级”。咱们一起向街道申请改造资金。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "岚哥……你不怪我撒谎了？你愿意帮我兜底？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "我怪你遇事逃避。但敢当众认错，就不算无可救药。记住，这不是拖延，是重生。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好。老街广播站，今天不报平安。咱们……报个新开始。"
        }
      ]
    }
